      // 三尾白狐（狐首真身）的三招：Codex 画的地面层 + 前景层逐帧图（20fps），地面层垫在人物底下、前景层盖在人物上面；
      // 图里施法者脚底在 cf、目标脚底在 tf，按实际站位把整段特效等比缩放对齐（引火的弹道、裂爪的落点才会对）
      const FOXFX = {"fire": {"n": 48, "cols": 8, "fw": 576, "fh": 324, "sc": 0.75, "contact": [23, 29, 35], "fps": 20, "cf": [124, 236], "tf": [426, 241]}, "claw": {"n": 40, "cols": 8, "fw": 576, "fh": 324, "sc": 0.75, "contact": [17, 19, 22], "fps": 20, "cf": [124, 236], "tf": [426, 241]}, "rain": {"n": 64, "cols": 8, "fw": 576, "fh": 324, "sc": 0.75, "contact": [30, 34, 39], "fps": 20, "cf": [124, 236], "tf": [426, 241]}}, FSH = {};
