        addFx({ life, layer: 1, draw(f) { frame(f, 'fx_fox_' + k + '_f'); const i = Math.floor(f.t * M.fps); while (hits < M.contact.length && i >= M.contact[hits]) { hits++; onHit(hits); } }, onEnd: res });
